  <script>
    /* ===========================================
       SLIDE PRESENTATION CONTROLLER
       - Keyboard navigation (←/→/Space/PageUp/PageDown)
       - Touch swipe
       - Wheel snap navigation
       - Progress bar + navigation dots
       - IntersectionObserver for reveal animations
       =========================================== */
    class SlidePresentation {
      constructor() {
        this.slides = Array.from(document.querySelectorAll('.slide'));
        this.currentSlide = 0;
        this.isAnimating = false;

        this.progress = document.querySelector('.progress-bar');
        this.nav = document.querySelector('.nav-dots');

        this.setupIntersectionObserver();
        this.setupNavDots();
        this.setupKeyboardNav();
        this.setupTouchNav();
        this.setupWheelNav();
        this.setupProgressBar();

        // Initialize
        this.goToSlide(0, { instant: true });
      }

      setupIntersectionObserver() {
        const obs = new IntersectionObserver(
          (entries) => {
            for (const entry of entries) {
              if (entry.isIntersecting) {
                entry.target.classList.add('visible');
              }
            }
          },
          { threshold: 0.35 }
        );
        this.slides.forEach((s) => obs.observe(s));
      }

      setupNavDots() {
        this.nav.innerHTML = '';
        this.dots = this.slides.map((slide, idx) => {
          const dot = document.createElement('button');
          dot.className = 'nav-dot';
          dot.setAttribute('aria-label', `Go to slide ${idx + 1}`);
          dot.addEventListener('click', () => this.goToSlide(idx));
          this.nav.appendChild(dot);
          return dot;
        });
        this.setActiveDot(0);
      }

      setActiveDot(index) {
        if (!this.dots) return;
        this.dots.forEach((d, i) => d.classList.toggle('active', i === index));
      }

      setupKeyboardNav() {
        window.addEventListener('keydown', (e) => {
          const key = e.key;
          if ([
            'ArrowRight', 'ArrowDown', 'PageDown', ' ', 'Spacebar'
          ].includes(key)) {
            e.preventDefault();
            this.next();
          }
          if (['ArrowLeft', 'ArrowUp', 'PageUp'].includes(key)) {
            e.preventDefault();
            this.prev();
          }
          if (key === 'Home') {
            e.preventDefault();
            this.goToSlide(0);
          }
          if (key === 'End') {
            e.preventDefault();
            this.goToSlide(this.slides.length - 1);
          }
        }, { passive: false });
      }

      setupTouchNav() {
        let startX = 0;
        let startY = 0;
        let isDown = false;

        const onStart = (x, y) => {
          startX = x;
          startY = y;
          isDown = true;
        };

        const onEnd = (x, y) => {
          if (!isDown) return;
          isDown = false;
          const dx = x - startX;
          const dy = y - startY;
          const ax = Math.abs(dx);
          const ay = Math.abs(dy);
          if (Math.max(ax, ay) < 40) return;
          // Prefer horizontal navigation
          if (ax > ay) {
            dx < 0 ? this.next() : this.prev();
          } else {
            dy < 0 ? this.next() : this.prev();
          }
        };

        window.addEventListener('touchstart', (e) => {
          const t = e.changedTouches[0];
          onStart(t.clientX, t.clientY);
        }, { passive: true });

        window.addEventListener('touchend', (e) => {
          const t = e.changedTouches[0];
          onEnd(t.clientX, t.clientY);
        }, { passive: true });
      }

      setupWheelNav() {
        let wheelLock = false;
        window.addEventListener('wheel', (e) => {
          if (wheelLock) return;
          const dy = e.deltaY;
          if (Math.abs(dy) < 10) return;
          wheelLock = true;
          dy > 0 ? this.next() : this.prev();
          setTimeout(() => { wheelLock = false; }, 520);
        }, { passive: true });
      }

      setupProgressBar() {
        window.addEventListener('scroll', () => {
          const maxScroll = document.documentElement.scrollHeight - window.innerHeight;
          const p = maxScroll > 0 ? window.scrollY / maxScroll : 0;
          this.progress.style.width = `${Math.max(0, Math.min(1, p)) * 100}%`;
        }, { passive: true });
      }

      next() {
        this.goToSlide(Math.min(this.currentSlide + 1, this.slides.length - 1));
      }

      prev() {
        this.goToSlide(Math.max(this.currentSlide - 1, 0));
      }

      goToSlide(index, opts = {}) {
        if (this.isAnimating && !opts.instant) return;
        if (index < 0 || index >= this.slides.length) return;

        this.currentSlide = index;
        this.setActiveDot(index);

        const target = this.slides[index];
        this.isAnimating = true;
        target.scrollIntoView({ behavior: opts.instant ? 'auto' : 'smooth' });
        setTimeout(() => { this.isAnimating = false; }, opts.instant ? 0 : 520);
      }
    }

    new SlidePresentation();
  </script>
</body>
</html>
