       =========================================== */
    * { margin: 0; padding: 0; box-sizing: border-box; }

    /* --- PASTE viewport-base.css CONTENTS HERE --- */
    /* ===========================================
       VIEWPORT FITTING: MANDATORY BASE STYLES
       Include this ENTIRE file in every presentation.
       These styles ensure slides fit exactly in the viewport.
       =========================================== */

    /* 1. Lock html/body to viewport */
    html, body {
        height: 100%;
        overflow-x: hidden;
    }

    html {
        scroll-snap-type: y mandatory;
        scroll-behavior: smooth;
    }

    /* 2. Each slide = exact viewport height */
    .slide {
        width: 100vw;
        height: 100vh;
        height: 100dvh; /* Dynamic viewport height for mobile browsers */
        overflow: hidden; /* CRITICAL: Prevent ANY overflow */
        scroll-snap-align: start;
        display: flex;
        flex-direction: column;
        position: relative;
    }

    /* 3. Content container with flex for centering */
    .slide-content {
        flex: 1;
        display: flex;
        flex-direction: column;
        justify-content: center;
        max-height: 100%;
        overflow: hidden; /* Double-protection against overflow */
        padding: var(--slide-padding);
    }

    /* 4. ALL typography uses clamp() for responsive scaling */
    :root {
        /* Titles scale from mobile to desktop */
        --title-size: clamp(1.5rem, 5vw, 4rem);
        --h2-size: clamp(1.25rem, 3.5vw, 2.5rem);
        --h3-size: clamp(1rem, 2.5vw, 1.75rem);

        /* Body text */
        --body-size: clamp(0.75rem, 1.5vw, 1.125rem);
        --small-size: clamp(0.65rem, 1vw, 0.875rem);

        /* Spacing scales with viewport */
        --slide-padding: clamp(1rem, 4vw, 4rem);
        --content-gap: clamp(0.5rem, 2vw, 2rem);
        --element-gap: clamp(0.25rem, 1vw, 1rem);
    }

    /* 5. Cards/containers use viewport-relative max sizes */
    .card, .container, .content-box {
        max-width: min(90vw, 1000px);
        max-height: min(80vh, 700px);
    }

    /* 6. Lists auto-scale with viewport */
    .feature-list, .bullet-list {
        gap: clamp(0.4rem, 1vh, 1rem);
    }

    .feature-list li, .bullet-list li {
        font-size: var(--body-size);
        line-height: 1.4;
    }

    /* 7. Grids adapt to available space */
    .grid {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(min(100%, 250px), 1fr));
        gap: clamp(0.5rem, 1.5vw, 1rem);
    }

    /* 8. Images constrained to viewport */
    img, .image-container {
        max-width: 100%;
        max-height: min(50vh, 400px);
        object-fit: contain;
    }

    /* ===========================================
       RESPONSIVE BREAKPOINTS
       Aggressive scaling for smaller viewports
       =========================================== */

    /* Short viewports (< 700px height) */
    @media (max-height: 700px) {
        :root {
            --slide-padding: clamp(0.75rem, 3vw, 2rem);
            --content-gap: clamp(0.4rem, 1.5vw, 1rem);
            --title-size: clamp(1.25rem, 4.5vw, 2.5rem);
            --h2-size: clamp(1rem, 3vw, 1.75rem);
        }
    }

    /* Very short viewports (< 600px height) */
    @media (max-height: 600px) {
        :root {
            --slide-padding: clamp(0.5rem, 2.5vw, 1.5rem);
            --content-gap: clamp(0.3rem, 1vw, 0.75rem);
            --title-size: clamp(1.1rem, 4vw, 2rem);
            --body-size: clamp(0.7rem, 1.2vw, 0.95rem);
        }

        /* Hide non-essential elements */
        .nav-dots, .keyboard-hint, .decorative {
            display: none;
        }
    }

    /* Extremely short (landscape phones, < 500px height) */
    @media (max-height: 500px) {
        :root {
            --slide-padding: clamp(0.4rem, 2vw, 1rem);
            --title-size: clamp(1rem, 3.5vw, 1.5rem);
            --h2-size: clamp(0.9rem, 2.5vw, 1.25rem);
            --body-size: clamp(0.65rem, 1vw, 0.85rem);
        }
    }

    /* Narrow viewports (< 600px width) */
    @media (max-width: 600px) {
        :root {
            --title-size: clamp(1.25rem, 7vw, 2.5rem);
        }

        /* Stack grids vertically */
        .grid {
            grid-template-columns: 1fr;
        }
    }

    /* ===========================================
       REDUCED MOTION
       Respect user preferences
       =========================================== */
    @media (prefers-reduced-motion: reduce) {
        *, *::before, *::after {
            animation-duration: 0.01ms !important;
            transition-duration: 0.2s !important;
        }

        html {
            scroll-behavior: auto;
        }
    }

    body {
      font-family: var(--font-body);
      color: var(--text0);
      background: radial-gradient(1200px 800px at 20% 10%, rgba(0, 255, 204, 0.13), transparent 60%),
                  radial-gradient(1000px 700px at 80% 20%, rgba(255, 53, 184, 0.10), transparent 55%),
                  radial-gradient(900px 650px at 70% 80%, rgba(214, 255, 0, 0.08), transparent 60%),
                  linear-gradient(135deg, var(--bg0), var(--bg2));
    }

    /* ===========================================
       GLOBAL UI: PROGRESS + NAV DOTS
       =========================================== */
    .progress-bar {
      position: fixed;
      top: 0;
      left: 0;
      height: clamp(2px, 0.35vh, 5px);
      width: 0;
      background: linear-gradient(90deg, var(--cyan), var(--magenta));
      z-index: 9999;
      box-shadow: 0 0 20px rgba(0,255,204,0.25);
      transform-origin: left center;
    }

    .nav-dots {
      position: fixed;
      right: clamp(10px, 1.4vw, 22px);
      top: 50%;
      transform: translateY(-50%);
      display: flex;
      flex-direction: column;
      gap: clamp(8px, 1.1vh, 14px);
      z-index: 9998;
    }

    .nav-dot {
      width: clamp(8px, 0.95vw, 12px);
      height: clamp(8px, 0.95vw, 12px);
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.20);
      border: 1px solid rgba(255,255,255,0.16);
      cursor: pointer;
      transition: transform 0.25s ease, background 0.25s ease, box-shadow 0.25s ease;
    }

    .nav-dot.active {
      background: rgba(0, 255, 204, 0.85);
      box-shadow: 0 0 0 6px rgba(0, 255, 204, 0.12);
      transform: scale(1.12);
    }

    .keyboard-hint {
      position: absolute;
      left: var(--slide-padding);
      bottom: calc(var(--slide-padding) * 0.75);
      font-size: var(--small-size);
      color: var(--text2);
      display: inline-flex;
      align-items: center;
      gap: 0.55rem;
    }

    .kbd {
      font-family: var(--font-mono);
      font-size: clamp(0.62rem, 0.9vw, 0.82rem);
      padding: 0.2em 0.55em;
      border-radius: 10px;
      border: 1px solid rgba(255,255,255,0.16);
      background: rgba(255,255,255,0.06);
      color: rgba(255,255,255,0.86);
    }

    /* ===========================================
       REVEAL ANIMATION
       =========================================== */
    .reveal {
      opacity: 0;
      transform: translateY(18px);
      filter: blur(6px);
      transition: opacity var(--dur) var(--ease-out-expo), transform var(--dur) var(--ease-out-expo), filter var(--dur) var(--ease-out-expo);
      will-change: transform, opacity;
    }

    .slide.visible .reveal {
      opacity: 1;
      transform: translateY(0);
      filter: blur(0);
    }

    .slide.visible .reveal.delay-1 { transition-delay: 0.06s; }
    .slide.visible .reveal.delay-2 { transition-delay: 0.14s; }
    .slide.visible .reveal.delay-3 { transition-delay: 0.22s; }
    .slide.visible .reveal.delay-4 { transition-delay: 0.30s; }

    /* ===========================================
       SHARED COMPONENTS
       =========================================== */
    .topline {
      font-family: var(--font-mono);
      font-size: clamp(0.7rem, 1.05vw, 0.95rem);
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: rgba(0, 255, 204, 0.9);
    }

    .h1 {
      font-family: var(--font-display);
      font-size: var(--title-size);
      line-height: 1.02;
      letter-spacing: -0.02em;
    }

    h2 {
      font-family: var(--font-display);
      font-size: var(--h2-size);
      line-height: 1.05;
      letter-spacing: -0.01em;
    }

    h3 {
      font-family: var(--font-display);
      font-size: var(--h3-size);
      line-height: 1.18;
      letter-spacing: -0.01em;
    }

    p {
      font-size: var(--body-size);
      line-height: 1.42;
      color: var(--text1);
    }

    .pill {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      padding: 0.35em 0.7em;
      border-radius: 999px;
      border: 1px solid rgba(255,255,255,0.16);
      background: rgba(255,255,255,0.06);
      color: rgba(255,255,255,0.86);
      font-family: var(--font-mono);
      font-size: clamp(0.65rem, 0.95vw, 0.9rem);
    }

    .card {
      background: linear-gradient(180deg, rgba(255,255,255,0.07), rgba(255,255,255,0.04));
      border: 1px solid rgba(255,255,255,0.14);
      border-radius: clamp(16px, 2vw, 22px);
      padding: clamp(0.9rem, 1.6vw, 1.35rem);
      box-shadow: 0 24px 60px rgba(0,0,0,0.35);
    }

    .grid-2 {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: clamp(0.75rem, 1.7vw, 1.35rem);
      align-items: stretch;
      max-height: 100%;
      overflow: hidden;
    }

    .grid-3 {
      display: grid;
      grid-template-columns: 1.15fr 1fr 1fr;
      gap: clamp(0.75rem, 1.7vw, 1.35rem);
      align-items: stretch;
      max-height: 100%;
      overflow: hidden;
    }

    .meta {
      font-family: var(--font-mono);
      color: var(--text2);
      font-size: clamp(0.65rem, 0.95vw, 0.9rem);
    }

    .subtle {
      color: var(--text2);
    }

    .accent {
      color: rgba(0, 255, 204, 0.95);
    }

    .accent2 {
      color: rgba(255, 53, 184, 0.95);
    }

    .divider {
      height: 1px;
      width: 100%;
      background: linear-gradient(90deg, rgba(0,255,204,0.0), rgba(0,255,204,0.55), rgba(255,53,184,0.55), rgba(255,53,184,0.0));
      margin: clamp(0.55rem, 1.4vh, 0.95rem) 0;
      opacity: 0.85;
    }

    /* ===========================================
       SLIDE SPECIFIC LAYOUTS
       =========================================== */

    /* Title */
    .title-slide .slide-content {
      justify-content: flex-end;
      gap: var(--content-gap);
    }

    .title-hero {
      display: grid;
      grid-template-columns: 1.05fr 0.95fr;
      gap: clamp(0.75rem, 2vw, 2.1rem);
      align-items: end;
      max-height: 100%;
      overflow: hidden;
    }

    .title-card {
      position: relative;
      padding: clamp(1.0rem, 2.1vw, 1.8rem);
      border-radius: clamp(18px, 2.3vw, 26px);
      background: linear-gradient(135deg, rgba(0,255,204,0.12), rgba(255,53,184,0.06) 55%, rgba(214,255,0,0.05));
      border: 1px solid rgba(255,255,255,0.14);
      overflow: hidden;
    }

    .title-card::before {
      content: "";
      position: absolute;
      inset: -2px;
      background: radial-gradient(700px 260px at 20% 15%, rgba(0,255,204,0.20), transparent 60%),
                  radial-gradient(560px 240px at 75% 35%, rgba(255,53,184,0.18), transparent 60%),
                  radial-gradient(600px 300px at 70% 90%, rgba(214,255,0,0.10), transparent 60%);
      filter: blur(0px);
      opacity: 0.85;
      pointer-events: none;
    }

    .title-card > * { position: relative; }

    .title-right {
      display: flex;
      flex-direction: column;
      gap: var(--content-gap);
      align-items: flex-start;
      justify-content: flex-end;
      max-height: 100%;
      overflow: hidden;
    }

    .logo-blob {
      width: min(100%, 420px);
      height: min(40vh, 340px);
      max-height: min(40vh, 340px);
      border-radius: 28px;
      border: 1px solid rgba(255,255,255,0.14);
      background:
        radial-gradient(110px 110px at 22% 28%, rgba(0,255,204,0.95), rgba(0,255,204,0.0) 65%),
        radial-gradient(160px 160px at 70% 42%, rgba(255,53,184,0.9), rgba(255,53,184,0.0) 70%),
        radial-gradient(210px 190px at 52% 78%, rgba(214,255,0,0.75), rgba(214,255,0,0.0) 70%),
        radial-gradient(430px 340px at 55% 55%, rgba(255,255,255,0.06), rgba(255,255,255,0.0) 60%);
      box-shadow: 0 40px 90px rgba(0,0,0,0.55);
      position: relative;
      overflow: hidden;
    }

    .logo-blob::after {
      content: "";
      position: absolute;
      inset: -40px;
      background: repeating-linear-gradient(
        90deg,
        rgba(255,255,255,0.0) 0px,
        rgba(255,255,255,0.0) 26px,
        rgba(255,255,255,0.05) 26px,
        rgba(255,255,255,0.05) 27px
      );
      transform: rotate(12deg);
      opacity: 0.5;
    }

    .authors {
      display: flex;
      flex-wrap: wrap;
      gap: 0.55rem;
      align-items: center;
    }

    /* Bullets */
    .bullet-list {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: clamp(0.55rem, 1.2vh, 0.95rem);
      padding-left: 0;
      margin-top: clamp(0.3rem, 0.9vh, 0.65rem);
    }

    .bullet-list li {
      display: grid;
      grid-template-columns: auto 1fr;
      gap: 0.6rem;
      align-items: start;
      color: var(--text1);
      font-size: var(--body-size);
      line-height: 1.42;
    }

    .bullet {
      width: clamp(10px, 1.1vw, 14px);
      height: clamp(10px, 1.1vw, 14px);
      margin-top: clamp(2px, 0.55vh, 6px);
      border-radius: 999px;
      background: radial-gradient(circle at 30% 30%, rgba(0,255,204,0.95), rgba(0,255,204,0.25) 55%, rgba(0,0,0,0) 70%);
      box-shadow: 0 0 0 4px rgba(0,255,204,0.10);
      flex: 0 0 auto;
    }

    /* Figure frames */
    .figure {
      border-radius: clamp(14px, 2vw, 20px);
      border: 1px solid rgba(255,255,255,0.14);
      background: rgba(255,255,255,0.04);
      overflow: hidden;
      position: relative;
      display: flex;
      flex-direction: column;
      justify-content: center;
      align-items: center;
      max-height: min(50vh, 420px);
    }

    .figure img {
      width: 100%;
      height: auto;
      max-height: min(44vh, 360px);
      object-fit: contain;
      display: block;
      filter: saturate(1.05) contrast(1.02);
    }

    .figure-cap {
      width: 100%;
      padding: 0.45rem 0.7rem;
      font-family: var(--font-mono);
      font-size: clamp(0.62rem, 0.9vw, 0.86rem);
      color: rgba(255,255,255,0.72);
      background: linear-gradient(180deg, rgba(0,0,0,0.0), rgba(0,0,0,0.55));
      position: absolute;
      bottom: 0;
      left: 0;
    }

    /* Data table */
    table {
      width: 100%;
      border-collapse: collapse;
      font-size: clamp(0.6rem, 0.95vw, 0.95rem);
      color: rgba(255,255,255,0.86);
      overflow: hidden;
      border-radius: clamp(12px, 1.6vw, 18px);
    }

    th, td {
      padding: clamp(0.45rem, 1.0vw, 0.7rem);
      border-bottom: 1px solid rgba(255,255,255,0.10);
    }

    th {
      text-align: left;
      font-family: var(--font-mono);
      letter-spacing: 0.06em;
      text-transform: uppercase;
      font-size: clamp(0.58rem, 0.9vw, 0.88rem);
      color: rgba(255,255,255,0.74);
      background: rgba(255,255,255,0.06);
    }

    tr:last-child td { border-bottom: none; }

    td strong {
      color: rgba(0,255,204,0.95);
      font-family: var(--font-mono);
      font-weight: 700;
    }

    .tag {
      font-family: var(--font-mono);
      font-size: clamp(0.62rem, 0.9vw, 0.85rem);
      padding: 0.18em 0.55em;
      border-radius: 999px;
      border: 1px solid rgba(255,255,255,0.12);
      background: rgba(255,255,255,0.05);
      color: rgba(255,255,255,0.8);
      white-space: nowrap;
    }

    .tag.os {
      border-color: rgba(255, 53, 184, 0.22);
      background: rgba(255, 53, 184, 0.10);
      color: rgba(255, 188, 229, 0.95);
    }

    .tag.smol {
      border-color: rgba(0, 255, 204, 0.22);
      background: rgba(0, 255, 204, 0.10);
      color: rgba(182, 255, 245, 0.95);
    }

    /* Mini chart */
    .bars {
      display: grid;
      gap: clamp(0.55rem, 1.4vh, 0.95rem);
      margin-top: clamp(0.4rem, 1.1vh, 0.85rem);
    }

    .bar-row {
      display: grid;
      grid-template-columns: clamp(150px, 18vw, 230px) 1fr clamp(86px, 10vw, 120px);
      gap: clamp(0.55rem, 1.4vw, 1.0rem);
      align-items: center;
    }

    .bar-label {
      font-family: var(--font-mono);
      font-size: clamp(0.7rem, 0.98vw, 0.92rem);
      color: rgba(255,255,255,0.84);
      line-height: 1.2;
    }

    .bar-track {
      height: clamp(10px, 1.2vh, 14px);
      border-radius: 999px;
      background: rgba(255,255,255,0.06);
      border: 1px solid rgba(255,255,255,0.10);
      overflow: hidden;
      position: relative;
    }

    .bar-fill {
      height: 100%;
      border-radius: 999px;
      background: linear-gradient(90deg, rgba(0,255,204,0.95), rgba(255,53,184,0.85));
      box-shadow: 0 0 22px rgba(0,255,204,0.18);
    }

    .bar-value {
      font-family: var(--font-mono);
      font-size: clamp(0.7rem, 0.98vw, 0.92rem);
      color: rgba(255,255,255,0.76);
      text-align: right;
      white-space: nowrap;
    }

    /* Pixel shuffle diagram */
    .ps-wrap {
      display: grid;
      grid-template-columns: 1.1fr 0.9fr;
      gap: clamp(0.75rem, 1.9vw, 1.35rem);
      align-items: center;
      max-height: 100%;
      overflow: hidden;
    }

    .ps-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: clamp(0.7rem, 1.6vw, 1.15rem);
      align-items: stretch;
    }

    .tensor {
      border-radius: clamp(14px, 1.7vw, 18px);
      border: 1px solid rgba(255,255,255,0.12);
      background: rgba(255,255,255,0.05);
      padding: clamp(0.65rem, 1.3vw, 1.05rem);
    }

    .tensor .label {
      font-family: var(--font-mono);
      font-size: clamp(0.6rem, 0.9vw, 0.82rem);
      color: rgba(255,255,255,0.70);
      letter-spacing: 0.06em;
      text-transform: uppercase;
      margin-bottom: clamp(0.45rem, 1.1vh, 0.7rem);
    }

    .cells {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: clamp(0.25rem, 0.6vw, 0.45rem);
    }

    .cell {
      aspect-ratio: 1;
      border-radius: 10px;
      border: 1px solid rgba(255,255,255,0.10);
      background: radial-gradient(circle at 30% 30%, rgba(0,255,204,0.85), rgba(0,255,204,0.08) 65%, rgba(0,0,0,0) 75%),
                  radial-gradient(circle at 70% 70%, rgba(255,53,184,0.60), rgba(255,53,184,0.0) 60%);
      opacity: 0.85;
    }

    .cells.compact {
      grid-template-columns: repeat(2, 1fr);
    }

    .arrow {
      align-self: center;
      justify-self: center;
      width: 100%;
      height: clamp(24px, 4.2vh, 42px);
      position: relative;
    }

    .arrow::before {
      content: "";
      position: absolute;
      left: 10%;
      right: 10%;
      top: 50%;
      height: 2px;
      background: linear-gradient(90deg, rgba(0,255,204,0.0), rgba(0,255,204,0.9), rgba(255,53,184,0.85), rgba(255,53,184,0.0));
      transform: translateY(-50%);
    }

    .arrow::after {
      content: "";
      position: absolute;
      right: 10%;
      top: 50%;
      width: 0;
      height: 0;
      border-left: 10px solid rgba(255,53,184,0.9);
      border-top: 7px solid transparent;
      border-bottom: 7px solid transparent;
      transform: translateY(-50%);
      filter: drop-shadow(0 0 10px rgba(255,53,184,0.25));
    }

    .callout {
      border-radius: clamp(14px, 1.7vw, 18px);
      border: 1px solid rgba(255,255,255,0.14);
      background: rgba(255,255,255,0.05);
      padding: clamp(0.85rem, 1.5vw, 1.15rem);
    }

    .callout .kpi {
      font-family: var(--font-display);
      font-size: clamp(1.35rem, 3.4vw, 2.7rem);
      letter-spacing: -0.02em;
      color: rgba(0,255,204,0.95);
      line-height: 1;
      margin-top: clamp(0.2rem, 0.8vh, 0.55rem);
    }

    .note {
      font-size: var(--small-size);
      color: rgba(255,255,255,0.64);
      line-height: 1.35;
      margin-top: clamp(0.25rem, 0.9vh, 0.65rem);
    }

    /* Footer */
    .footer {
      position: absolute;
      left: var(--slide-padding);
      right: var(--slide-padding);
      bottom: calc(var(--slide-padding) * 0.55);
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 1rem;
      pointer-events: none;
      font-family: var(--font-mono);
      font-size: clamp(0.62rem, 0.9vw, 0.86rem);
      color: rgba(255,255,255,0.55);
      opacity: 0.95;
    }

    .footer .left {
      display: inline-flex;
      align-items: center;
      gap: 0.6rem;
      min-width: 0;
    }

    .chip {
      pointer-events: none;
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      padding: 0.26em 0.6em;
      border-radius: 999px;
      border: 1px solid rgba(255,255,255,0.12);
      background: rgba(255,255,255,0.05);
